function slidingWindowCount(arr, windowSize) {
    if (arr.length < windowSize) return [];

    const result = [];
    for (let i = 0; i <= arr.length - windowSize; i++) {
        result.push(arr.slice(i, i + windowSize).reduce((sum, val) => sum + val, 0));
    }
    return result;
}
